<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useApi } from '../composables/useApi'
const {apiFetch}=useApi()
const backups=ref<any[]>([]),containers=ref<any[]>([]),projects=ref<any[]>([]),volumes=ref<any[]>([]),recoveryStatus=ref<any>(null)
const error=ref(''),message=ref(''),busy=ref(false),passphrase=ref(''),archive=ref<File|null>(null)
const selection=ref<any>({instance:true,projects:[],volumes:[],databases:[],stop_containers:[]})
const database=ref({container:'',engine:'postgres',database:'',user:'postgres'})
const settings=ref<any>({remote_url:'',retain_count:14,retain_days:30,schedule_hours:0,selection:{}})
const restoreId=ref(''),restorePass=ref(''),plan=ref<any>(null),mapping=ref<any>({volumes:{},projects:{},databases:[],instance_volume:''})
const selectedEntries=ref<Record<string,boolean>>({})
let loadedSettings=false
async function load(){error.value='';await Promise.allSettled([
 (async()=>{try{backups.value=await apiFetch<any[]>('/api/recovery/backups')}catch(e:any){error.value=e.message}})(),
 (async()=>{try{const data:any=await apiFetch('/api/recovery/inventory');containers.value=data.containers;volumes.value=data.volumes;projects.value=data.projects}catch(e:any){error.value=e.message}})(),
 (async()=>{try{settings.value=await apiFetch('/api/recovery/settings');if(!loadedSettings){if(settings.value.selection?.instance || ['projects','volumes','databases'].some(key=>settings.value.selection?.[key]?.length))selection.value={...settings.value.selection};loadedSettings=true}}catch(e:any){error.value=e.message}})(),
 (async()=>{try{recoveryStatus.value=await apiFetch('/api/recovery/status')}catch(e:any){error.value=e.message}})()
])}

function addDatabase(){if(!database.value.container || !database.value.database)return;selection.value.databases.push({...database.value});database.value={container:'',engine:'postgres',database:'',user:'postgres'}}
async function backup(){busy.value=true;error.value='';try{const result:any=await apiFetch('/api/recovery/backups',{method:'POST',body:JSON.stringify({...selection.value,passphrase:passphrase.value})});passphrase.value='';message.value='Backup started. Track operation '+result.operation_id+'. Keep your recovery key separately.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function download(id:string){try{const ticket:any=await apiFetch('/api/recovery/'+id+'/download-ticket',{method:'POST'});const link=document.createElement('a');link.href=ticket.url;link.download='docktun-recovery.dtrec';link.click()}catch(e:any){error.value=e.message}}
async function upload(){if(!archive.value)return;busy.value=true;error.value='';try{const result:any=await apiFetch('/api/recovery/import',{method:'POST',body:archive.value,headers:{'Content-Type':'application/octet-stream'}});restoreId.value=result.id;message.value='Encrypted archive imported. Enter its recovery key to verify contents.';archive.value=null;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function requestMapping(){const request:any={passphrase:restorePass.value,volumes:{},projects:{},databases:[],instance_volume:''};for(const entry of plan.value?.manifest?.entries||[]){if(!selectedEntries.value[entry.file])continue;if(entry.kind==='instance')request.instance_volume=mapping.value.instance_volume;if(entry.kind==='volume')request.volumes[entry.name]=mapping.value.volumes[entry.name];if(entry.kind==='project')request.projects[entry.name]=mapping.value.projects[entry.name];if(entry.kind==='database'){const target=mapping.value.databases.find((d:any)=>d.entry===entry.file);if(target)request.databases.push({...target})}}return request}
async function inspect(){busy.value=true;error.value='';try{const result:any=await apiFetch('/api/recovery/'+restoreId.value+'/inspect',{method:'POST',body:JSON.stringify(plan.value?requestMapping():{passphrase:restorePass.value})});if(!plan.value){const suffix=restoreId.value.slice(0,8);mapping.value={instance_volume:'docktun-restored-'+suffix,volumes:{},projects:{},databases:[]};selectedEntries.value={};for(const entry of result.manifest.entries){if(entry.kind==='volume')mapping.value.volumes[entry.name]=entry.name+'-restored-'+suffix;if(entry.kind==='project')mapping.value.projects[entry.name]='/opt/projects/'+entry.name+'-restored';if(entry.kind==='database')mapping.value.databases.push({entry:entry.file,container:'',database:entry.database,user:entry.user})}}plan.value=result;backups.value=await apiFetch<any[]>('/api/recovery/backups');message.value='Archive decrypted and checksums verified. This does not yet establish a successful application restore.'}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function restore(){if(!confirm('Create only the mapped new destinations and restore selected data? Database targets must be empty. Review the plan and retain the encrypted source archive.'))return;busy.value=true;error.value='';try{const result:any=await apiFetch('/api/recovery/'+restoreId.value+'/restore',{method:'POST',body:JSON.stringify(requestMapping())});restorePass.value='';message.value='Restore started. Inspect operation '+result.id+' before starting recovered applications.';plan.value=null;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function saveSettings(){busy.value=true;error.value='';try{settings.value.selection={...selection.value,passphrase:''};await apiFetch('/api/recovery/settings',{method:'PUT',body:JSON.stringify(settings.value)});message.value='Schedule, retention and destination saved';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function remoteUpload(id:string){busy.value=true;try{await apiFetch('/api/recovery/'+id+'/remote-upload',{method:'POST'});message.value='Remote encrypted object uploaded and read-back checksum verified';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function remoteFetch(id:string){busy.value=true;try{const item:any=await apiFetch('/api/recovery/'+id+'/remote-fetch',{method:'POST'});restoreId.value=item.id;plan.value=null;message.value='Remote encrypted archive imported. Verify it with the separately held recovery key.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function removeLocal(id:string){if(!confirm('Remove this local encrypted archive? This cannot be undone here. Keep a verified external copy and its recovery key.'))return;busy.value=true;try{await apiFetch('/api/recovery/'+id,{method:'DELETE'});message.value='Local archive removed';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function timestamp(value:any){return value?.Valid?new Date(value.Int64*1000).toLocaleString():'Pending'}
async function activate(){if(!confirm('Have you reviewed recovered host paths, provider identities and notification destinations? Normal reconciliation will resume after a core restart.'))return;try{const result:any=await apiFetch('/api/recovery/activate',{method:'POST',body:JSON.stringify({confirmed:true})});message.value=result.note}catch(e:any){error.value=e.message}}
onMounted(load)
</script>
<template>
<section class="cyber-card space-y-5" aria-label="Encrypted recovery">
 <div class="flex flex-wrap justify-between gap-3"><div><h2 class="font-semibold">Encrypted backup &amp; recovery</h2><p class="text-xs text-muted mt-1">Project files, consistent database exports, explicitly quiesced volumes, and the DockTun instance.</p></div><button class="cyber-btn-secondary" @click="load">Refresh</button></div>
 <div v-if="recoveryStatus?.review_required" class="rounded-lg border border-amber-300 bg-amber-50 p-3 text-sm"><strong>Recovered instance needs review</strong><p class="mt-1">{{recoveryStatus.note}}</p><button class="cyber-btn-secondary mt-2" @click="activate">Confirm recovery review</button></div>
 <p v-if="error" role="alert" class="text-red-600 text-sm">{{error}}</p><p v-if="message" role="status" class="text-emerald-800 text-sm">{{message}}</p>
 <details><summary class="font-medium cursor-pointer">Create an encrypted backup</summary><form class="space-y-4 mt-3" @submit.prevent="backup">
 <label class="flex gap-2 text-sm"><input v-model="selection.instance" type="checkbox">DockTun instance: consistent account database, signing key and selected configuration</label>
 <fieldset class="space-y-1"><legend class="font-medium text-sm">Project files (volume data excluded)</legend><label v-for="project in projects" :key="project.id" class="flex gap-2 text-xs"><input v-model="selection.projects" type="checkbox" :value="project.id">{{project.name}}</label></fieldset>
 <fieldset class="space-y-1"><legend class="font-medium text-sm">Named volume snapshots</legend><p class="text-xs text-muted">Every running container writing a selected volume must be explicitly selected for stopping below. Use a database export when downtime is not acceptable.</p><label v-for="volume in volumes" :key="volume.name" class="flex gap-2 text-xs"><input v-model="selection.volumes" type="checkbox" :value="volume.name">{{volume.name}}</label></fieldset>
 <fieldset class="space-y-1"><legend class="font-medium text-sm">Explicitly stop and resume these volume writers</legend><label v-for="container in containers" :key="container.id" class="flex gap-2 text-xs"><input v-model="selection.stop_containers" type="checkbox" :value="container.id">{{container.name}} · {{container.state}}</label></fieldset>
 <fieldset class="space-y-2"><legend class="text-sm font-medium">Consistent database exports</legend><div class="grid sm:grid-cols-2 gap-2"><select v-model="database.container" class="cyber-input text-xs"><option value="">Select database container</option><option v-for="container in containers" :key="container.id" :value="container.id">{{container.name}}</option></select><select v-model="database.engine" class="cyber-input text-xs"><option>postgres</option><option>mysql</option><option>mariadb</option></select><input v-model="database.database" class="cyber-input text-xs" placeholder="Database name"><input v-model="database.user" class="cyber-input text-xs" placeholder="Authorized database account"></div><button type="button" class="cyber-btn-secondary text-xs" @click="addDatabase">Add database selection</button><p v-for="(entry,index) in selection.databases" :key="index" class="text-xs">{{entry.engine}} · {{entry.database}} · {{entry.user}} <button type="button" class="underline" @click="selection.databases.splice(index,1)">Remove</button></p><p class="text-xs text-muted">Uses the selected container's existing authorized local database access. Database passwords are not requested or exported as separate credentials.</p></fieldset>
 <label class="block text-sm font-medium">Separately held recovery passphrase<input v-model="passphrase" type="password" minlength="12" autocomplete="new-password" class="cyber-input w-full mt-1"></label><p class="text-xs text-amber-800">Without this key the archive cannot be recovered. Keep it off the Docker host. Plaintext snapshots exist temporarily inside the protected data directory while encryption runs.</p><button class="cyber-btn" :disabled="busy || passphrase.length<12">Create encrypted backup</button>
 </form></details>
 <details><summary class="font-medium cursor-pointer">Schedule, retention &amp; remote storage</summary><div class="space-y-3 mt-3"><label class="block text-xs">HTTPS/WebDAV collection URL<input v-model="settings.remote_url" class="cyber-input w-full" placeholder="https://backup.example/collection"></label><div class="grid sm:grid-cols-3 gap-2"><label class="text-xs">Retain at least this many local archives<input v-model.number="settings.retain_count" type="number" min="1" max="1000" class="cyber-input w-full"></label><label class="text-xs">Minimum age before retirement (days)<input v-model.number="settings.retain_days" type="number" min="1" class="cyber-input w-full"></label><label class="text-xs">Backup interval (hours; 0 disables)<input v-model.number="settings.schedule_hours" type="number" min="0" max="168" class="cyber-input w-full"></label></div><p class="text-xs text-muted">Schedules use the selections above and require a separately mounted DOCKTUN_BACKUP_KEY_FILE. Optional remote authorization comes from DOCKTUN_BACKUP_REMOTE_AUTH_FILE. Remote objects are verified by downloading and hashing them. Local retention preserves the latest restored archive and will not retire an unverified, unuploaded copy. Remote deletion is deliberately separate.</p><button class="cyber-btn-secondary" :disabled="busy" @click="saveSettings">Save settings and selected resources</button></div></details>
 <div class="space-y-2"><h3 class="text-sm font-medium">Archive history</h3><article v-for="item in backups" :key="item.id" class="border rounded-lg p-3 text-xs"><div class="flex justify-between gap-2"><strong>{{item.phase}}</strong><span>{{new Date(item.created_at*1000).toLocaleString()}}</span></div><p class="break-all mt-1">{{item.id}} · {{Math.round(item.size/1024/1024)}} MiB</p><p class="text-muted mt-1">Decrypted integrity: {{timestamp(item.integrity_verified_at)}} · Selected restore completed: {{timestamp(item.restored_at)}} · Remote read-back: {{timestamp(item.remote_uploaded_at)}}</p><p v-if="item.error" class="text-amber-800">{{item.error}}</p><div class="flex flex-wrap gap-2 mt-2"><button v-if="['complete','imported'].includes(item.phase)" class="cyber-btn-secondary" @click="download(item.id)">Download encrypted archive</button><button v-if="['complete','imported'].includes(item.phase)" class="cyber-btn-secondary" @click="restoreId=item.id;plan=null">Inspect / restore</button><button v-if="settings.remote_url && item.phase==='complete'" class="cyber-btn-secondary" :disabled="busy" @click="remoteUpload(item.id)">Upload &amp; verify remote</button><button v-if="settings.remote_url && item.phase==='not_local' && item.remote_uploaded_at?.Valid" class="cyber-btn-secondary" :disabled="busy" @click="remoteFetch(item.id)">Retrieve remote archive</button><button v-if="['complete','imported'].includes(item.phase)" class="cyber-btn-secondary" :disabled="busy" @click="removeLocal(item.id)">Remove local copy</button></div></article><p v-if="!backups.length" class="text-xs text-muted">No recovery archives yet.</p></div>
 <details open><summary class="font-medium cursor-pointer">Import and restore</summary><div class="space-y-3 mt-3"><input type="file" accept=".dtrec" class="text-xs" @change="archive=($event.target as HTMLInputElement).files?.[0]||null"><button class="cyber-btn-secondary text-xs" :disabled="busy || !archive" @click="upload">Import encrypted file</button><label class="block text-xs">Archive ID<input v-model="restoreId" class="cyber-input w-full" @input="plan=null"></label><label class="block text-xs">Recovery passphrase<input v-model="restorePass" type="password" autocomplete="off" class="cyber-input w-full"></label><button class="cyber-btn-secondary" :disabled="busy || !restoreId || restorePass.length<12" @click="inspect">Verify archive / refresh restore plan</button>
 <div v-if="plan" class="space-y-3"><p class="text-xs text-muted">Select objects and new destinations, then refresh the plan before restoring.</p><div v-for="entry in plan.manifest.entries" :key="entry.file" class="border rounded p-3 space-y-2 text-xs"><label class="flex gap-2"><input v-model="selectedEntries[entry.file]" type="checkbox" @change="plan.ready=false"><strong>{{entry.kind}} · {{entry.name}}</strong><span>{{Math.round(entry.size/1024)}} KiB</span></label><input v-if="entry.kind==='instance'" v-model="mapping.instance_volume" class="cyber-input w-full" placeholder="New instance volume" @input="plan.ready=false"><input v-if="entry.kind==='volume'" v-model="mapping.volumes[entry.name]" class="cyber-input w-full" placeholder="New volume" @input="plan.ready=false"><input v-if="entry.kind==='project'" v-model="mapping.projects[entry.name]" class="cyber-input w-full" placeholder="Unused absolute project folder" @input="plan.ready=false"><div v-if="entry.kind==='database'" class="space-y-2"><select v-model="mapping.databases.find((d:any)=>d.entry===entry.file).container" class="cyber-input w-full" @change="plan.ready=false"><option value="">Choose explicitly prepared empty database target</option><option v-for="container in containers" :key="container.id" :value="container.id">{{container.name}}</option></select><input v-model="mapping.databases.find((d:any)=>d.entry===entry.file).database" class="cyber-input w-full" placeholder="Empty database name" @input="plan.ready=false"><input v-model="mapping.databases.find((d:any)=>d.entry===entry.file).user" class="cyber-input w-full" placeholder="Authorized account" @input="plan.ready=false"></div></div><p v-for="check in plan.checks" :key="check.id" class="text-xs" :class="check.status==='failed'?'text-red-600':'text-emerald-700'">{{check.label}}: {{check.message}}</p><details v-if="plan.instance_compose"><summary class="cursor-pointer text-sm">Recovery Compose preview</summary><pre class="text-xs whitespace-pre-wrap overflow-auto bg-slate-50 p-3">{{plan.instance_compose}}</pre></details><p v-for="note in plan.instructions" :key="note" class="text-xs text-amber-800">{{note}}</p><button class="cyber-btn" :disabled="busy || !plan.ready" @click="restore">Restore verified selections</button></div>
 </div></details>
</section>
</template>
